const assertRetainedReceipt=(actual,fresh)=>{assert.ok(actual.items.every(item=>!Object.hasOwn(item,'confirmed_folders')&&!Object.hasOwn(item,'confirmed_flags')),'Retained status/replay never emits an older flag or membership snapshot');assert.deepEqual(actual,{...fresh,items:fresh.items.map(({confirmed_folders:_folders,confirmed_flags:_flags,...item})=>item)});};
