const barrier=()=>{let release;const promise=new Promise(resolve=>{release=resolve;});return {promise,release};};
function journal(){
 const rows=new Map(),locks=new Set();let failFinish=false;
 const check=(scope,value)=>{if(value&&!['org_id','owner_id','installation_id'].every(key=>value.plan.binding.scope[key]===scope[key]))throw Error('Cross scope');};
 return {rows,set failFinish(value){failFinish=value;},async load(scope,id){const value=rows.get(id)??null;check(scope,value);return structuredClone(value);},
  async create(plan){const prior=rows.get(plan.operation_id);if(prior){if(prior.plan.digest!==plan.digest)throw Object.assign(Error('Conflict'),{code:'EMAIL_TRIAGE_OPERATION_CONFLICT'});return structuredClone(prior);}
   const value={plan:structuredClone(plan),items:plan.items.map(item=>({logical_id:item.logical_id,state:'prepared'}))};rows.set(plan.operation_id,value);return structuredClone(value);},
  async change(scope,id,work){if(locks.has(id))throw Object.assign(Error('Busy'),{code:'EMAIL_TRIAGE_BUSY'});locks.add(id);
   try{const value=structuredClone(rows.get(id)??null);check(scope,value);return await work(value,async next=>{
    if(failFinish&&next.items.some(item=>['succeeded','unknown','failed'].includes(item.state)))throw Error('Synthetic durable finish loss');
    rows.set(id,structuredClone(next));});}finally{locks.delete(id);}}
 };
}
