test('actual registered native human triage reuses provider operations, durable reservation and exact logical receipt without Experience',async()=>{
 for(const provider of ['gmail','microsoft'])for(const kind of ['mark_read','mark_unread','star','unstar','archive','trash','move']){
  const f=await fixture(provider),input=request(f,kind,kind==='move'?{destination:{account_id:f.binding.account_id,provider,id:provider==='gmail'?'custom-label':'custom-folder',kind:provider==='gmail'?'label':'folder'}}:{});
  const result=await f.adapter.nativeEmailTriage(input,f.context);assert.equal(result.schema_version,'deft.email_native_triage_result.v1');assert.equal(result.items[0].logical_message_id,f.source.logical_message_id);assert.equal(result.items[0].state,'succeeded');assert.equal(result.items[0].undo_supported,true);assert.equal(result.automatic_retry,false);assert.equal(result.operation,kind);
  assert.deepEqual(result.items[0].confirmed_flags,{seen:kind==='mark_read'||provider==='gmail'&&kind==='trash',flagged:kind==='star',answered:null},'Actual provider-confirmed journal state reaches native receipt');
  assert.equal(f.calls.filter(call=>call.init.method!=='GET').length,1);assert.equal(JSON.stringify(result).includes('locator'),false);
  const count=f.calls.length;assertRetainedReceipt(await f.adapter.nativeEmailTriage(input,f.context),result);assert.equal(f.calls.length,count,'Replay executes no provider reads or writes');
  assertRetainedReceipt(await f.adapter.nativeEmailTriage({mode:'status',operation_id:input.operation_id},f.context),result);assert.equal(f.calls.length,count,'Status returns persisted confirmation without provider I/O');
  if(kind==='mark_read')assert.equal(provider==='gmail'?f.labels.includes('UNREAD'):!f.graph.isRead,false);
  if(kind==='star')assert.equal(provider==='gmail'?f.labels.includes('STARRED'):f.graph.flag.flagStatus==='flagged',true);
 }
});
