test('M23 recovery25 target partial receipt preserves unrelated labels and no provider IDs or automatic replay',async()=>{
 const f=await fixture(),index=new LogicalMailIndex(f.binding.scope),states=new Map(),sources=[];let writes=0;for(let i=0;i<25;i++){const id='recovery-'+i,locator={kind:'gmail',message_id:id,thread_id:'thread-'+i,label_ids:['INBOX','UNREAD','keep']};states.set(id,[...locator.label_ids]);sources.push(providerSourceForParent(f.account,index.upsert(f.binding.scope,{account_id:f.binding.account_id,provider:'gmail',locator})));}
 f.handler=(href,init)=>{const path=new URL(href).pathname,match=/\/messages\/([^/]+)(?:\/modify)?$/u.exec(path);assert.ok(match);const id=match[1];if(id==='recovery-13')return json({error:{message:'Synthetic missing'}},404);if(init.method==='GET')return json({id,labelIds:states.get(id)});assert.ok([...f.ledger.rows.values()].some(value=>value.items.some(item=>item.state==='started')));const body=JSON.parse(init.body);assert.deepEqual(body,{addLabelIds:['SPAM'],removeLabelIds:['INBOX']});writes++;const after=[...new Set([...states.get(id).filter(label=>!body.removeLabelIds.includes(label)),...body.addLabelIds])].sort();states.set(id,after);return json({id,labelIds:after});};
 const input={...request(f,'spam'),sources},v=await f.adapter.nativeEmailTriage(input,f.context);assert.equal(v.items.length,25);assert.equal(v.items.filter(item=>item.state==='succeeded').length,24);assert.equal(v.items.filter(item=>item.state==='failed').length,1);for(const item of v.items)assert.equal(Object.hasOwn(item,'confirmed_flags'),item.state==='succeeded','Only newly completed partial items carry flags');assert.equal(writes,24);assert.deepEqual(new Set(v.items.map(item=>item.logical_message_id)),new Set(sources.map(source=>source.logical_message_id)));assert.equal(JSON.stringify(v).includes('recovery-'),false);for(const [id,labels]of states){assert.ok(labels.includes('keep')&&labels.includes('UNREAD'));if(id!=='recovery-13')assert.ok(labels.includes('SPAM')&&!labels.includes('INBOX'));}const count=f.calls.length;assertRetainedReceipt(await f.adapter.nativeEmailTriage(input,f.context),v);assert.equal(f.calls.length,count);
});
